(5708146, 829191, 86799, '<td valign="top">Very nice.  Maintained just enough sharpness to be a landscape rather than an abstract.  Good work with the border, too.</td>', 'Very nice.  Maintained just enough sharpness to be a landscape rather than an abstract.  Good work with the border, too.', '2009-11-01 07:09:24.000000', NULL, 1),
(5708155, 829784, 86799, '<td valign="top">Love this.  The swirl is very interesting and distinct, and adds to the subject without becoming the subject.  Good stuff.  Hope you score very high.  I''ll help.</td>', 'Love this.  The swirl is very interesting and distinct, and adds to the subject without becoming the subject.  Good stuff.  Hope you score very high.  I''ll help.', '2009-11-01 07:11:48.000000', NULL, 1),
