INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5714931, 829857, 93565, '<td valign="top">I''ve done some similar messing around using the same technique, only with the addition of using zoom and camera rotation while doing so. You can get some pretty cool effects if you do all of this with street lights, if you''re curious. Some I''ve gotten don''t look anything like photos at all, looking more like graphic design projects. Fun stuff.<br/>Regarding the actual image itself- I''m not liking the choice for the border color, but I like the photo itself. It reminds me of a patchwork, or maybe the term threadbare is more what I''m going for.<br/><br/><i>Message edited by author 2009-11-05 02:12:20.</i></td>', 'I''ve done some similar messing around using the same technique, only with the addition of using zoom and camera rotation while doing so. You can get some pretty cool effects if you do all of this with street lights, if you''re curious. Some I''ve gotten don''t look anything like photos at all, looking more like graphic design projects. Fun stuff.Regarding the actual image itself- I''m not liking the choice for the border color, but I like the photo itself. It reminds me of a patchwork, or maybe the term threadbare is more what I''m going for.', '2009-11-05 02:11:01.000000', '2009-11-05 02:12:20.000000', 0),
